/// Spec-style helper: true iff `n` is a power of two (and positive).
/// Note: This is a runtime function in Rust (there is no `spec fn` in stable Rust).
pub fn is_2_pow(n: i64) -> bool {
    n > 0 && (n & (n - 1)) == 0
}

/// Return the lower-bound insertion index for `x` in the sorted subrange `a[lo..hi)`.
/// Preconditions (assumed by the caller):
/// - lo <= hi
/// - hi <= a.len()
/// - a[lo..hi) is sorted nondecreasing
///
/// Postcondition:
/// Returns k in [lo, hi] such that:
/// - for all r in [lo, k): a[r] < x
/// - for all r in [k, hi): a[r] >= x
pub fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    debug_assert!(lo <= hi);
    debug_assert!(hi <= a.len());

    let mut l = lo;
    let mut r = hi; // exclusive
    while l < r {
        let m = l + (r - l) / 2;
        if a[m] < x {
            l = m + 1;
        } else {
            r = m;
        }
    }
    l
}

/// Return the lower bound insertion index for `x` considering only the first 1000 elements.
/// Assumes `a.len() >= 1000` and `a[0..1000)` is sorted nondecreasing.
/// The result k is in [0, 1000].
pub fn search_1000(a: &[i32], x: i32) -> usize {
    assert!(a.len() >= 1000, "array length must be at least 1000");
    search_range_helper(a, x, 0, 1000)
}

