        while prefix.len() < 1000 {
            prefix.push(5);
        }
        let a = prefix;

        assert_eq!(search_1000(&a, 0), 0);   // before all
        assert_eq!(search_1000(&a, 1), 0);   // first 1
        assert_eq!(search_1000(&a, 2), 3);   // first 2
        assert_eq!(search_1000(&a, 3), 5);   // between 2 and 5
